using System;

class Container<T>
{
    [Attr<T>]
    class C1
    {
    }

    [AttrContainer<T>.Attr]
    class C2
    {
    }

    [AttrContainer<T>.B.Attr]
    class C3
    {
    }

    [Attr<T[]>]
    class C4
    {
    }
}

class Attr<T> : Attribute { }

class AttrContainer<T>
{  
    public class Attr : Attribute
    {
        public T Value { get; set; }
    }

    public class B
    {
        public class Attr : Attribute
        {
        }
    }
}

